INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT145-S4-Q1$batch09$, 145, 4, 1, $batch09$Principle-Strengthen$batch09$, $batch09$Pundit: Grenier will almost certainly not be elected as mayor. Although she says she believes in raising city employees’ wages, it was only a few years ago that she was arguing that their wages should not be increased. Her claim that she has learned more about the issue since then—though sincere—will not matter to most voters, who will see her as insincere.$batch09$, $batch09$Which one of the following principles, if valid, most helps to justify the pundit’s reasoning?$batch09$, $batch09$A$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=145 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Voters are unlikely to vote for a politician whom they perceive to be insincere.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Voters are unlikely to notice whether a politician’s stance on issues has changed over time.$batch09$, $batch09$Opposite$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Voters are unlikely to be influenced by what a politician’s views were in the past if the voters agree with the politician’s current positions.$batch09$, $batch09$Opposite$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Voters are likely to elect a politician who they believe understands their financial concerns.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Voters are likely to question the sincerity of a politician who does not hold the same beliefs they do.$batch09$, $batch09$Wrong Trigger$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Grenier almost certainly won't be elected mayor.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Grenier recently argued against raising city employees' wages and now supports it. Grenier's explanation, sincere as it is, won't matter, because most voters will see Grenier as insincere.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The evidence ends with voters seeing Grenier as insincere. The conclusion is that Grenier loses. The missing link: voters don't vote for politicians they think are insincere.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Voters are unlikely to vote for a politician they see as insincere.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Most voters will see Grenier as insincere, and A says voters are unlikely to vote for such a politician. That leads straight to Grenier losing.$batch09$), ($batch09$B$batch09$, $batch09$If voters don't notice changes in stance, the flip-flop wouldn't hurt Grenier. The pundit says voters will notice and react.$batch09$), ($batch09$C$batch09$, $batch09$If voters agree with Grenier's current position on wages, this says the old views won't matter. That would help Grenier.$batch09$), ($batch09$D$batch09$, $batch09$The pundit's reasoning is about sincerity, not whether voters think Grenier understands their finances.$batch09$), ($batch09$E$batch09$, $batch09$The voters doubt Grenier because the stance changed, not because Grenier's beliefs differ from theirs. And E only predicts doubt. It doesn't get us to losing the election.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT145-S4-Q1$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
